"""Build the generated parts of the website from index.html and content.json.

1. Section pages: /research/, /publications/ … are copies of index.html with their own title, description,
   canonical address and sharing preview, so each section can be found in search and shared on its own.
   The page script reads the address and opens that section.
2. feed.xml: an RSS feed of the "Latest" news on the homepage.
3. Lighter images: WebP copies of every photo in /images at a few widths (images/w/), listed in
   images/w/index.json. The page uses them when they exist and falls back to the original otherwise.

Run by .github/workflows/sitemap.yml whenever index.html, content.json or an image changes, before the sitemap.
"""
import html
import json
import pathlib
import re
import subprocess
from datetime import datetime, timezone
from email.utils import format_datetime

ROOT = pathlib.Path(__file__).resolve().parents[2]
SITE = "https://shagbaor.com"
GEN_MARK = "<!-- generated by .github/scripts/build_site.py from index.html; edit index.html instead -->"


def slug(s):
    s = str(s or "section").lower().replace("&", "and")
    s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
    return s or "section"


def plain(md):
    """Markdown-ish text to plain text."""
    t = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", str(md or ""))
    t = re.sub(r"[*_`]", "", t)
    return re.sub(r"\s+", " ", t).strip()


def visible(items):
    return [i for i in (items or []) if i and not i.get("hidden")]


def set_meta(page, prop, value, attr="property"):
    v = html.escape(value, quote=True)
    pat = re.compile(r'(<meta %s="%s" content=")[^"]*(">)' % (attr, re.escape(prop)))
    return pat.sub(lambda m: m.group(1) + v + m.group(2), page, count=1)


# ---------------------------------------------------------------- section pages
def sections_of(c):
    out, used = [], {}
    for s in c.get("sections", []):
        if not s or s.get("show") is False:
            continue
        i = slug(s.get("id") or s.get("nav_label") or s.get("heading"))
        while i in used:
            i += "-2"
        used[i] = 1
        out.append((i, s))
    return out


def jsonld_for(sid, s, c):
    person = {"@type": "Person", "name": c.get("hero", {}).get("name") or "Shagbaor Hycent Amool", "url": SITE + "/"}
    graph = []
    if s.get("type") == "resources":
        for t in visible(s.get("items")):
            url = t.get("url") or ""
            item = {
                "@type": "SoftwareApplication",
                "name": plain(t.get("name")),
                "description": plain(t.get("text"))[:300],
                "applicationCategory": "EducationalApplication",
                "operatingSystem": "Any (web browser)",
                "isAccessibleForFree": True,
                "offers": {"@type": "Offer", "price": "0", "priceCurrency": "USD"},
                "author": person,
                "url": (SITE + url) if url.startswith("/") else url,
            }
            if t.get("doi"):
                item["identifier"] = "https://doi.org/" + t["doi"]
            graph.append(item)
    if s.get("type") == "links" and sid == "publications":
        for p in visible(s.get("items")):
            cat = p.get("category") or ""
            if not cat:
                continue
            url = p.get("url") or ""
            kind = {"Journal Articles": "ScholarlyArticle", "Conferences": "ScholarlyArticle", "Software": "SoftwareSourceCode"}.get(cat, "CreativeWork")
            year = re.search(r"(19|20)\d\d", p.get("label") or "")
            item = {
                "@type": kind,
                "name": plain(p.get("title")),
                "author": [{"@type": "Person", "name": a.strip()} for a in re.split(r",\s*(?:&\s*)?|\s&\s", plain(p.get("authors"))) if a.strip() and len(a.strip()) > 2] or [person],
                "url": url,
            }
            if year:
                item["datePublished"] = year.group(0)
            if url.startswith("https://doi.org/"):
                item["identifier"] = url
            if p.get("plain"):
                item["abstract"] = plain(p["plain"])
            if cat == "Journal Articles" and p.get("text"):
                item["isPartOf"] = {"@type": "Periodical", "name": plain(p["text"]).split(",")[0]}
            graph.append(item)
    if not graph:
        return ""
    return '<script type="application/ld+json">' + json.dumps({"@context": "https://schema.org", "@graph": graph}, ensure_ascii=False) + "</script>"


def build_sections(c, template):
    site = c.get("site", {})
    site_title = site.get("title") or "Shagbaor Hycent Amool"
    pages = [(i, s.get("nav_label") or s.get("heading"), plain(s.get("subtitle") or s.get("lede") or ""), s) for i, s in sections_of(c)]
    contact = c.get("contact", {})
    if contact.get("show") is not False:
        pages.append(("contact", contact.get("nav_label") or "Contact", "Email, profiles, booking a meeting and the speaker & press kit for " + (c.get("hero", {}).get("name") or "Shagbaor Hycent Amool") + ".", {}))
    written = []
    for sid, label, desc, s in pages:
        title = "%s · %s" % (plain(label), site_title)
        desc = desc or site.get("description") or ""
        url = "%s/%s/" % (SITE, sid)
        p = template
        p = re.sub(r"<title>[^<]*</title>", "<title>%s</title>" % html.escape(title), p, count=1)
        p = re.sub(r'<link rel="canonical" href="[^"]*">', '<link rel="canonical" href="%s">' % url, p, count=1)
        p = set_meta(p, "description", desc, "name")
        p = set_meta(p, "og:url", url)
        p = set_meta(p, "og:title", title)
        p = set_meta(p, "og:description", desc)
        p = set_meta(p, "og:type", "website")
        p = set_meta(p, "twitter:title", title, "name")
        p = set_meta(p, "twitter:description", desc, "name")
        ld = jsonld_for(sid, s, c)
        p = p.replace("</head>", (ld + "\n" if ld else "") + GEN_MARK + "\n</head>", 1)
        out = ROOT / sid / "index.html"
        if out.exists() and GEN_MARK not in out.read_text(encoding="utf-8"):
            print("skipped %s: a folder with that name already holds another page" % sid)
            continue
        out.parent.mkdir(exist_ok=True)
        out.write_text(p, encoding="utf-8")
        written.append(sid)
    # remove pages for sections that no longer exist
    for d in ROOT.iterdir():
        f = d / "index.html"
        if d.is_dir() and f.exists() and d.name not in written and GEN_MARK in f.read_text(encoding="utf-8"):
            f.unlink()
            try:
                d.rmdir()
            except OSError:
                pass
    (ROOT / "assets" / "sections.json").write_text(json.dumps(written) + "\n", encoding="utf-8")
    print("section pages:", ", ".join(written))
    return written


# ---------------------------------------------------------------- RSS feed
def build_feed(c):
    site = c.get("site", {})
    g = c.get("glance", {})
    items = []
    for n in visible(g.get("news")):
        text = plain(n.get("text"))
        m = re.search(r"\]\(([^)\s]+)\)", n.get("text") or "")
        link = n.get("url") or (m.group(1) if m else "/")
        if link.startswith("/"):
            link = SITE + link
        try:
            d = datetime.strptime(n.get("iso") or "", "%Y-%m-%d").replace(tzinfo=timezone.utc)
        except ValueError:
            d = None
        items.append((d, text, link))
    for p in visible(next((s for s in c.get("sections", []) if s.get("id") == "publications"), {}).get("items")):
        if p.get("category") == "Journal Articles":
            items.append((None, "Published: " + plain(p.get("title")), p.get("url") or SITE + "/publications/"))
    out = ['<?xml version="1.0" encoding="UTF-8"?>',
           '<?xml-stylesheet type="text/xsl" href="/feed.xsl"?>',
           '<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">', "<channel>",
           "<title>%s</title>" % html.escape(c.get("hero", {}).get("name") or "Shagbaor Hycent Amool"),
           "<link>%s/</link>" % SITE,
           '<atom:link href="%s/feed.xml" rel="self" type="application/rss+xml"/>' % SITE,
           "<description>%s</description>" % html.escape("New tools, publications, talks and news from " + (c.get("hero", {}).get("name") or "Shagbaor Hycent Amool") + "."),
           "<language>en</language>"]
    for d, text, link in items:
        title = text if len(text) <= 110 else text[:107].rsplit(" ", 1)[0] + "…"
        out.append("<item><title>%s</title><link>%s</link><guid isPermaLink=\"false\">%s</guid><description>%s</description>%s</item>" % (
            html.escape(title), html.escape(link), html.escape(link + "#" + slug(text)[:60]), html.escape(text),
            "<pubDate>%s</pubDate>" % format_datetime(d) if d else ""))
    out += ["</channel>", "</rss>", ""]
    (ROOT / "feed.xml").write_text("\n".join(out), encoding="utf-8")
    print("feed.xml: %d items" % len(items))


# ---------------------------------------------------------------- lighter images
WIDTHS = (480, 960, 1600)


def build_images():
    try:
        from PIL import Image, ImageOps
    except ImportError:
        print("Pillow not installed; skipping images")
        return
    src_dir, out_dir = ROOT / "images", ROOT / "images" / "w"
    out_dir.mkdir(exist_ok=True)
    index = {}
    for f in sorted(src_dir.iterdir()):
        if f.suffix.lower() not in (".jpg", ".jpeg", ".png") or f.name.startswith(("og-", "apple-touch", "icon-")):
            continue
        try:
            im = Image.open(f)
            im = ImageOps.exif_transpose(im)
        except Exception as e:  # noqa: BLE001
            print("skip", f.name, e)
            continue
        w0 = im.width
        widths = [w for w in WIDTHS if w < w0] + [min(w0, WIDTHS[-1])]
        widths = sorted(set(widths))
        stem = f.stem
        for w in widths:
            out = out_dir / ("%s-%d.webp" % (stem, w))
            if out.exists() and out.stat().st_mtime >= f.stat().st_mtime:
                continue
            im2 = im if w == w0 else im.resize((w, round(im.height * w / w0)), Image.LANCZOS)
            if im2.mode not in ("RGB", "RGBA"):
                im2 = im2.convert("RGBA" if "A" in im2.getbands() else "RGB")
            im2.save(out, "WEBP", quality=78, method=6)
        index[f.name] = widths
    for old in out_dir.glob("*.webp"):
        stem, _, w = old.stem.rpartition("-")
        if not any(pathlib.Path(n).stem == stem and int(w) in ws for n, ws in index.items() if w.isdigit()):
            old.unlink()
    (out_dir / "index.json").write_text(json.dumps(index, indent=0, sort_keys=True) + "\n", encoding="utf-8")
    print("images:", len(index))


def main():
    c = json.loads((ROOT / "content.json").read_text(encoding="utf-8"))
    template = (ROOT / "index.html").read_text(encoding="utf-8")
    build_sections(c, template)
    build_feed(c)
    build_images()


if __name__ == "__main__":
    main()
